-- Icon Browser: GM-only browser for every Interface\Icons texture in the client.
--
-- The icon list lives in IconBrowserIcons.lua (generated by gen_icon_list.py).
-- The addon only displays base-game client data; it changes nothing and sends no
-- chat commands, so it needs no server-side permission or audit record.

local ADDON, ns = ...

local COLUMNS, ROWS = 8, 6
local PAGE_SIZE = COLUMNS * ROWS
local CELL = 44
local ICON_SIZE = 36
local REFORGED_MARKER = "#"
local SOURCES = { "all", "stock", "reforged" }
local SOURCE_LABELS = { all = "All sources", stock = "Stock only", reforged = "Reforged only" }

-- ---------------------------------------------------------------- icon data --

ns.Icons = {}
ns.loaded = false

-- Building 30,830 entries costs a few tens of milliseconds and about 9 MB, which should not be
-- paid at login by every character when the browser may never be opened. The raw list is
-- dropped once ingested, so only the parsed entries stay resident.
local function LoadIcons()
    if ns.loaded then
        return #ns.Icons
    end
    ns.loaded = true
    if type(IconBrowserIcons) ~= "table" then
        return 0
    end
    for _, entry in ipairs(IconBrowserIcons) do
        local name, tag = entry, "stock"
        if entry:sub(-1) == REFORGED_MARKER then
            name = entry:sub(1, -2)
            tag = "reforged"
        end
        ns.Icons[#ns.Icons + 1] = { name = name, tag = tag, lower = name:lower() }
    end
    IconBrowserIcons = nil
    return #ns.Icons
end

ns.LoadIcons = LoadIcons

ns.State = { search = "", source = "all", page = 1, matches = {} }

-- Pure filter used by the frame and the offline test.
function ns.Filter(search, source)
    local needle = (search or ""):lower()
    local out = {}
    for _, icon in ipairs(ns.Icons) do
        if (source == "all" or icon.tag == source)
            and (needle == "" or icon.lower:find(needle, 1, true)) then
            out[#out + 1] = icon
        end
    end
    return out
end

function ns.Path(name)
    return "Interface\\Icons\\" .. name
end

function ns.TagLabel(tag)
    return tag == "reforged" and "Reforged (patch-I)" or "Stock 3.3.5a"
end

-- ---------------------------------------------------------------- the frame --

local frame = CreateFrame("Frame", "IconBrowserFrame", UIParent)
frame:SetWidth(452)
frame:SetHeight(514)
frame:SetPoint("CENTER")
frame:SetFrameStrata("DIALOG")
frame:SetClampedToScreen(true)
frame:SetMovable(true)
frame:EnableMouse(true)
frame:RegisterForDrag("LeftButton")
frame:SetScript("OnDragStart", function(self) self:StartMoving() end)
frame:SetScript("OnDragStop", function(self) self:StopMovingOrSizing() end)
frame:SetBackdrop({
    bgFile = "Interface\\DialogFrame\\UI-DialogBox-Background",
    edgeFile = "Interface\\DialogFrame\\UI-DialogBox-Border",
    tile = true,
    tileSize = 16,
    edgeSize = 16,
    insets = { left = 4, right = 4, top = 4, bottom = 4 },
})
frame:Hide()
tinsert(UISpecialFrames, "IconBrowserFrame")

local title = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge")
title:SetPoint("TOPLEFT", frame, "TOPLEFT", 18, -14)
title:SetText("Icon Browser")

local close = CreateFrame("Button", nil, frame, "UIPanelCloseButton")
close:SetPoint("TOPRIGHT", frame, "TOPRIGHT", -4, -4)

local function Box(parent, width, height)
    -- Plain EditBox with an explicit backdrop: InputBoxTemplate's middle texture does not
    -- render reliably on this client.
    local box = CreateFrame("EditBox", nil, parent)
    box:SetWidth(width)
    box:SetHeight(height)
    box:SetAutoFocus(false)
    box:SetFontObject(ChatFontNormal)
    box:SetTextColor(1, 1, 1)
    box:SetJustifyH("LEFT")
    box:SetTextInsets(6, 6, 0, 0)
    box:SetBackdrop({
        bgFile = "Interface\\ChatFrame\\ChatFrameBackground",
        edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border",
        tile = true,
        tileSize = 8,
        edgeSize = 8,
        insets = { left = 1, right = 1, top = 1, bottom = 1 },
    })
    box:SetBackdropColor(0, 0, 0, 0.8)
    box:SetBackdropBorderColor(0.55, 0.45, 0.25, 1)
    -- A focused edit box swallows Escape; close the frame in the same press.
    box:SetScript("OnEscapePressed", function(self)
        self:ClearFocus()
        frame:Hide()
    end)
    return box
end

local searchBox = Box(frame, 236, 22)
searchBox:SetPoint("TOPLEFT", frame, "TOPLEFT", 22, -44)
searchBox:SetMaxLetters(80)
searchBox:SetScript("OnTextChanged", function(self)
    ns.SetSearch(self:GetText())
end)
searchBox:SetScript("OnEnterPressed", function(self) self:ClearFocus() end)
ns.searchBox = searchBox

local sourceButton = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate")
sourceButton:SetWidth(160)
sourceButton:SetHeight(22)
sourceButton:SetPoint("TOPLEFT", frame, "TOPLEFT", 270, -44)
sourceButton:SetText(SOURCE_LABELS.all)
sourceButton:SetScript("OnClick", function()
    local index = 1
    for i, source in ipairs(SOURCES) do
        if source == ns.State.source then
            index = i
            break
        end
    end
    ns.SetSource(SOURCES[index % #SOURCES + 1])
end)
ns.sourceButton = sourceButton

local countLabel = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
countLabel:SetPoint("TOPLEFT", frame, "TOPLEFT", 270, -74)
countLabel:SetTextColor(1, 0.82, 0.3)
countLabel:SetJustifyH("RIGHT")
countLabel:SetWidth(160)
ns.countLabel = countLabel

local grid = CreateFrame("Frame", nil, frame)
grid:SetWidth(COLUMNS * CELL)
grid:SetHeight(ROWS * CELL)
grid:SetPoint("TOPLEFT", frame, "TOPLEFT", 50, -92)

ns.Buttons = {}
for row = 1, ROWS do
    for column = 1, COLUMNS do
        local button = CreateFrame("Button", nil, grid)
        button:SetWidth(ICON_SIZE)
        button:SetHeight(ICON_SIZE)
        button:SetPoint("TOPLEFT", grid, "TOPLEFT", (column - 1) * CELL, -(row - 1) * CELL)

        local icon = button:CreateTexture(nil, "ARTWORK")
        icon:SetWidth(ICON_SIZE)
        icon:SetHeight(ICON_SIZE)
        icon:SetPoint("CENTER", button, "CENTER", 0, 0)
        icon:SetTexCoord(0.07, 0.93, 0.07, 0.93)
        button.icon = icon

        local highlight = button:CreateTexture(nil, "HIGHLIGHT")
        highlight:SetWidth(ICON_SIZE)
        highlight:SetHeight(ICON_SIZE)
        highlight:SetPoint("CENTER", button, "CENTER", 0, 0)
        highlight:SetTexture("Interface\\Buttons\\ButtonHilight-Square")
        highlight:SetBlendMode("ADD")

        button:SetScript("OnEnter", function(self)
            local entry = self.entry
            if not entry then return end
            GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
            GameTooltip:SetText(entry.name)
            GameTooltip:AddLine(ns.TagLabel(entry.tag), 0.7, 0.7, 0.7)
            GameTooltip:AddLine("Click to copy the path", 0.9, 0.9, 0.9)
            GameTooltip:Show()
        end)
        button:SetScript("OnLeave", function() GameTooltip:Hide() end)
        button:SetScript("OnClick", function(self)
            local entry = self.entry
            if not entry then return end
            ns.CopyPath(entry.name)
        end)
        ns.Buttons[#ns.Buttons + 1] = button
    end
end

local prev = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate")
prev:SetWidth(70)
prev:SetHeight(22)
prev:SetPoint("TOPLEFT", frame, "TOPLEFT", 22, -364)
prev:SetText("< Prev")
prev:SetScript("OnClick", function() ns.SetPage(ns.State.page - 1) end)
ns.prevButton = prev

local pageLabel = frame:CreateFontString(nil, "OVERLAY", "GameFontNormal")
pageLabel:SetPoint("TOPLEFT", frame, "TOPLEFT", 100, -368)
pageLabel:SetWidth(220)
pageLabel:SetJustifyH("CENTER")
ns.pageLabel = pageLabel

local next = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate")
next:SetWidth(70)
next:SetHeight(22)
next:SetPoint("TOPLEFT", frame, "TOPLEFT", 330, -364)
next:SetText("Next >")
next:SetScript("OnClick", function() ns.SetPage(ns.State.page + 1) end)
ns.nextButton = next

local copyCaption = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
copyCaption:SetPoint("TOPLEFT", frame, "TOPLEFT", 22, -398)
copyCaption:SetText("Texture path - selected when you click an icon, press Ctrl+C")

local copyBox = Box(frame, 404, 22)
copyBox:SetPoint("TOPLEFT", frame, "TOPLEFT", 22, -418)
copyBox:SetMaxLetters(200)
ns.copyBox = copyBox

local footer = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
footer:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", 18, 14)
footer:SetWidth(410)
footer:SetJustifyH("LEFT")
footer:SetTextColor(0.6, 0.6, 0.6)
footer:SetText("Data comes from the client's own icon textures. A question mark means the client " ..
    "cannot find that texture.")

-- ------------------------------------------------------------- state changes --

function ns.CopyPath(name)
    local path = ns.Path(name)
    copyBox:SetText(path)
    copyBox:SetFocus()
    copyBox:HighlightText()
    return path
end

function ns.SetSearch(text)
    ns.State.search = text or ""
    ns.Refresh(true)
end

function ns.SetSource(source)
    ns.State.source = source
    sourceButton:SetText(SOURCE_LABELS[source] or SOURCE_LABELS.all)
    ns.Refresh(true)
end

function ns.SetPage(page)
    local maxPage = math.max(1, math.ceil(#ns.State.matches / PAGE_SIZE))
    if page < 1 then page = 1 end
    if page > maxPage then page = maxPage end
    ns.State.page = page
    ns.Render()
end

function ns.Render()
    local state = ns.State
    local offset = (state.page - 1) * PAGE_SIZE
    for index, button in ipairs(ns.Buttons) do
        local entry = state.matches[offset + index]
        if entry then
            button.entry = entry
            button.icon:SetTexture(ns.Path(entry.name))
            button:Show()
        else
            button.entry = nil
            button:Hide()
        end
    end
    local maxPage = math.max(1, math.ceil(#state.matches / PAGE_SIZE))
    pageLabel:SetText(string.format("Page %d / %d", state.page, maxPage))
    countLabel:SetText(string.format("%d matches", #state.matches))
end

function ns.Refresh(resetPage)
    if resetPage then
        ns.State.page = 1
    end
    ns.State.matches = ns.Filter(ns.State.search, ns.State.source)
    ns.SetPage(ns.State.page)
end

-- --------------------------------------------------------------- slash code --

SLASH_ICONBROWSER1 = "/icons"
SLASH_ICONBROWSER2 = "/iconbrowser"
SlashCmdList["ICONBROWSER"] = function()
    if frame:IsShown() then
        frame:Hide()
        return
    end
    if LoadIcons() == 0 then
        DEFAULT_CHAT_FRAME:AddMessage(
            "Icon Browser: IconBrowserIcons.lua is missing or empty; "
                .. "regenerate it with tools/icon-browser/gen_icon_list.py"
        )
        return
    end
    frame:Show()
    ns.Refresh()
end

ns.frame = frame

DEFAULT_CHAT_FRAME:AddMessage("Icon Browser loaded: /icons")
